#!/usr/bin/env python3
"""Remove executable JavaScript from an HTML file in place."""
import sys
from html.parser import HTMLParser
from pathlib import Path


class JavaScriptFilter(HTMLParser):
    VOID_ELEMENTS = {
        "area", "base", "br", "col", "embed", "hr", "img", "input",
        "link", "meta", "param", "source", "track", "wbr",
    }

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.output = []
        self.drop_script = 0
        self.drop_textarea = 0

    @staticmethod
    def _js_url(value):
        if value is None:
            return False
        # Ignore whitespace and control characters often used to obscure the scheme.
        compact = "".join(ch for ch in value if ord(ch) > 32 and ord(ch) != 127)
        return compact.lower().startswith("javascript:")

    def handle_starttag(self, tag, attrs):
        tag_lower = tag.lower()
        if self.drop_script:
            if tag_lower == "script":
                self.drop_script += 1
            return
        if self.drop_textarea:
            if tag_lower == "textarea":
                self.drop_textarea += 1
            return
        if tag_lower == "script":
            self.drop_script = 1
            return
        kept = []
        for name, value in attrs:
            lname = name.lower()
            if lname.startswith("on") or self._js_url(value):
                continue
            kept.append((name, value))
        self.output.append("<" + tag)
        for name, value in kept:
            self.output.append(" " + name)
            if value is not None:
                escaped = value.replace("&", "&amp;").replace('"', "&quot;")
                self.output.append('="' + escaped + '"')
        self.output.append(">")

    def handle_startendtag(self, tag, attrs):
        tag_lower = tag.lower()
        if self.drop_script or self.drop_textarea or tag_lower == "script":
            return
        kept = [(n, v) for n, v in attrs
                if not n.lower().startswith("on") and not self._js_url(v)]
        self.output.append("<" + tag)
        for name, value in kept:
            self.output.append(" " + name)
            if value is not None:
                escaped = value.replace("&", "&amp;").replace('"', "&quot;")
                self.output.append('="' + escaped + '"')
        self.output.append(" />")

    def handle_endtag(self, tag):
        tag_lower = tag.lower()
        if self.drop_script:
            if tag_lower == "script":
                self.drop_script -= 1
            return
        if self.drop_textarea:
            if tag_lower == "textarea":
                self.drop_textarea -= 1
            return
        if tag_lower == "textarea":
            self.output.append("</" + tag + ">")
            return
        self.output.append("</" + tag + ">")

    def handle_data(self, data):
        if not self.drop_script and not self.drop_textarea:
            self.output.append(data)

    def handle_entityref(self, name):
        if not self.drop_script and not self.drop_textarea:
            self.output.append("&" + name + ";")

    def handle_charref(self, name):
        if not self.drop_script and not self.drop_textarea:
            self.output.append("&#" + name + ";")

    def handle_comment(self, data):
        if not self.drop_script and not self.drop_textarea:
            self.output.append("<!--" + data + "-->")

    def handle_decl(self, decl):
        if not self.drop_script and not self.drop_textarea:
            self.output.append("<!" + decl + ">")

    def handle_pi(self, data):
        if not self.drop_script and not self.drop_textarea:
            self.output.append("<?" + data + ">")


def main():
    path = Path(sys.argv[1])
    text = path.read_text(encoding="utf-8")
    parser = JavaScriptFilter()
    parser.feed(text)
    parser.close()
    path.write_text("".join(parser.output), encoding="utf-8")


if __name__ == "__main__":
    main()
